insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 164, 'പുനരുത്ഥാനം', null, 896 from books where volume_id=1 and book_no=31 on conflict (book_id, chapter_no) do nothing;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 165, 'ആദ്യമായി വസ്ത്രം ധരിപ്പിക്കപ്പെടുന്നവൻ', null, 897 from books where volume_id=1 and book_no=31 on conflict (book_id, chapter_no) do nothing;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ جَابِرِ بْنِ عَبْدِاللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أُعْطِيتُ خَمْسًا، لَمْ يُعْطَهُنَّ أَحَدٌ قَبْلِي: نُصِرْتُ بِالرُّعْبِ مَسِيرَةَ شَهْرٍ، وَجُعِلَتْ لِيَ الْأَرْضُ مَسْجِدًا وَطَهُورًا، فَأَيُّمَا رَجُلٍ مِنْ أُمَّتِي أَدْرَكَتْهُ الصَّلَاةُ فَلْيُصَلِّ، وَأُحِلَّتْ لِيَ الْمَغَانِمُ وَلَمْ تَحِلَّ لِأَحَدٍ قَبْلِي، وَأُعْطِيتُ الشَّفَاعَةَ، وَكَانَ النَّبِيُّ يُبْعَثُ إِلَى قَوْمِهِ خَاصَّةً، وَبُعِثْتُ إِلَى النَّاسِ عَامَّةً". (خ,ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ) പറഞ്ഞു: "എനിക്കുമുമ്പ് മറ്റാർക്കും നൽകപ്പെടാത്ത അഞ്ചു കാര്യങ്ങൾ എനിക്ക് നൽകപ്പെട്ടിരിക്കുന്നു; ഒരു മാസത്തെ വഴിയകലെ വെച്ച് ശത്രുവിനുണ്ടാകുന്ന ഭയം കൊണ്ട് എനിക്ക് സഹായം നൽകപ്പെട്ടു. ഭൂമി മുഴുവനും എനിക്ക് പള്ളിയും ശുദ്ധീകരണ വസ്തുവുമായി നിശ്ചയിക്കപ്പെട്ടു. അതിനാൽ എന്റെ സമുദായത്തിലെ ഏത് വ്യക്തിക്കും നിസ്കാര സമയമായാൽ അവൻ നിസ്കരിച്ചു കൊള്ളട്ടെ. യുദ്ധസമ്പത്ത് എനിക്കനുവദിക്കപ്പെട്ടിരിക്കുന്നു. എനിക്കുമുമ്പ് ആർക്കും അതനുവദിക്കപ്പെട്ടിരുന്നില്ല. പരലോകത്ത് ശഫാഅത്തി(ശുപാർശ)നുള്ള അധികാരം എനിക്ക് നൽകപ്പെട്ടു. മുൻ പ്രവാചകന്മാർ നിയോഗിക്കപ്പെട്ടത് സ്വന്തം സമുദായങ്ങളിലേക്കായിരുന്നു. ഞാൻ എല്ലാ മനുഷ്യർക്കും വേണ്ടി നിയോഗിക്കപ്പെട്ടു." (ബു,ന)', 'جَابِرِ بْنِ عَبْدِاللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 193, 193, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: خَرَجْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي بَعْضِ أَسْفَارِهِ، حَتَّى إِذَا كُنَّا بِالْبَيْدَاءِ، أَوْ بِذَاتِ الْجَيْشِ، انْقَطَعَ عِقْدٌ لِي، فَأَقَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى الْتِمَاسِهِ، وَأَقَامَ النَّاسُ مَعَهُ، وَلَيْسُوا عَلَى مَاءٍ، فَأَتَى النَّاسُ إِلَى أَبِي بَكْرٍ الصِّدِّيقِ رَضِيَ اللهُ عَنْهُ، فَقَالُوا: أَلَا تَرَى مَا صَنَعَتْ عَائِشَةُ رَضِيَ اللهُ عَنْهَا؟ أَقَامَتْ بِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَالنَّاسِ، وَلَيْسُوا عَلَى مَاءٍ، وَلَيْسَ مَعَهُمْ مَاءٌ، فَجَاءَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ، وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَاضِعٌ رَأْسَهُ عَلَى فَخِذِي قَدْ نَامَ، فَقَالَ: حَبَسْتِ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَالنَّاسَ، وَلَيْسُوا عَلَى مَاءٍ، وَلَيْسَ مَعَهُمْ مَاءٌ، فَقَالَتْ عَائِشَةُ رَضِيَ اللهُ عَنْهَا: فَعَاتَبَنِي أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ، وَقَالَ مَا شَاءَ اللهُ أَنْ يَقُولَ، وَجَعَلَ يَطْعُنُنِي بِيَدِهِ فِي خَاصِرَتِي، فَلَا يَمْنَعُنِي مِنَ التَّحَرُّكِ إِلَّا مَكَانُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى فَخِذِي، فَقَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ أَصْبَحَ عَلَى غَيْرِ مَاءٍ، فَأَنْزَلَ اللهُ آيَةَ التَّيَمُّمِ "فَتَيَمَّمُوا" فَقَالَ أُسَيْدُ بْنُ الْحُضَيْرِ رَضِيَ اللهُ عَنْهُ: مَا هِيَ بِأَوَّلِ بَرَكَتِكُمْ يَا آلَ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُ، قَالَتْ: فَبَعَثْنَا الْبَعِيرَ الَّذِي كُنْتُ عَلَيْهِ، فَأَصَبْنَا الْعِقْدَ تَحْتَهُ. (خ,د,ن,جه)', 'ആഇശ(റ): ഒരു യാത്രയിൽ ഞങ്ങൾ റസൂലി(സ)നോടൊപ്പം പുറപ്പെട്ടു. ഞങ്ങൾ ''ബൈദാ'' എന്നോ ''ദാതുൽജൈൽ'' എന്നോ പേരുള്ള സ്ഥലത്തെത്തിയപ്പോൾ എന്റെ ഒരു മാല അറ്റുപോയി. അതന്വേഷിക്കാനായി നബി(സ)യും അനുചരരന്മാരും അവിടെ താമസിച്ചു. അവിടെ വെള്ളമുണ്ടായിരുന്നില്ല. ജനങ്ങൾ അബൂബക്കറി(റ)ന്റെ അടുക്കൽ ചെന്നു പറഞ്ഞു: കണ്ടില്ലേ, ആഇശ ചെയ്ത പണി, അവർ നബി(സ)യെയും അനുചരന്മാരെയും വെള്ളമില്ലാത്ത സ്ഥലത്ത് തടഞ്ഞുവെച്ചിരിക്കുന്നു. അബൂബക്കർ എന്റെ അടുക്കൽ വന്നു. അപ്പോൾ നബി(സ) എന്റെ മടിയിൽ തല വെച്ചുറങ്ങിയിരുന്നു. അദ്ദേഹം ചോദിച്ചു: നബി(സ)യെയും അനുചരന്മാരെയും വെള്ളമില്ലാത്ത സ്ഥലത്ത് നീ തടഞ്ഞു വെച്ചിരിക്കുന്നോ? ആഇശ(റ) പറയുന്നു: അദ്ദേഹം എന്നെ ആക്ഷേപിച്ചു വളരെയധികം സംസാരിച്ചു. കൈ കൊണ്ട് എന്റെ ഊരക്ക് കുത്തുകയും ചെയ്തു. എന്റെ മടിയിൽ നബി(സ) തലവെച്ചതു കൊണ്ട് ഞാൻ അനങ്ങിയില്ല. അങ്ങനെ വെള്ളമില്ലാത്ത അവസ്ഥയിൽ നബി(സ) എഴുന്നേറ്റു. അപ്പോഴാണ് "തയമ്മമൂ" (നിങ്ങൾ തയമ്മും ചെയ്യുക) എന്ന തയമ്മുമിന്റെ സൂക്തം അല്ലാഹു അവതരിച്ചത്. ഈ സന്ദർഭത്തിൽ ഉസൈദുബ്നു ഹുളൈർ(റ) പറഞ്ഞു: അബൂബക്കറിന്റെ കുടുംബമേ, ഇത് നിങ്ങളുടെ വക ഒന്നാമത്തെ അനുഗ്രഹമല്ല. ആഇശ(റ) തുടർന്നു: പിന്നീട് ഞാൻ കയറിയിരുന്ന ഒട്ടകത്തെ എഴുന്നേൽപിച്ചപ്പോൾ അതിന്റെ ചുവട്ടിൽ നിന്നുമാലയും കിട്ടി. (ബു,ദ,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','د','ن','جه']::text[], array['ബു','ദ','ന','ജ']::text[], null, null, 193, 194, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ الْخُزَاعِيِّ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنَّا فِي سَفَرٍ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَإِنَّا أَسْرَيْنَا حَتَّى كُنَّا فِي آخِرِ اللَّيْلِ وَقَعْنَا وَقْعَةً وَلَا وَقْعَةَ أَحْلَى عِنْدَ الْمُسَافِرِ مِنْهَا فَمَا أَيْقَظَنَا إِلَّا حَرُّ الشَّمْسِ، وَكَانَ أَوَّلَ مَنِ اسْتَيْقَظَ فُلَانٌ ثُمَّ فُلَانٌ ثُمَّ عُمَرُ ابْنُ الْخَطَّابِ الرَّابِعُ، وَكَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا نَامَ لَمْ نُوقِظْهُ حَتَّى يَكُونَ هُوَ يَسْتَيْقِظُ، فَإِنَّا لَا نَدْرِي مَا يَحْدُثُ لَهُ فِي نَوْمِهِ، فَلَمَّا اسْتَيْقَظَ عُمَرُ وَرَأَى مَا أَصَابَ النَّاسَ، وَكَانَ رَجُلًا جَلِيدًا، فَكَبَّرَ وَرَفَعَ صَوْتَهُ بِالتَّكْبِيرِ، فَمَا زَالَ يُكَبِّرُ وَيَرْفَعُ صَوْتَهُ بِالتَّكْبِيرِ حَتَّى اسْتَيْقَظَ بِصَوْتِهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا اسْتَيْقَظَ شَكَوْا إِلَيْهِ الَّذِي أَصَابَهُمْ، قَالَ: "لَا ضَيْرَ أَوْ لَا يَضِيرُ، ارْتَحِلُوا". فَارْتَحَلُوا فَسَارَ غَيْرَ بَعِيدٍ، ثُمَّ نَزَلَ فَدَعَا بِالْوَضُوءِ فَتَوَضَّأَ، وَنُودِيَ بِالصَّلَاةِ فَصَلَّى بِالنَّاسِ، فَلَمَّا انْفَتَلَ مِنْ صَلَاتِهِ إِذَا هُوَ بِرَجُلٍ مُعْتَزِلٍ لَمْ يُصَلِّ مَعَ الْقَوْمِ، قَالَ: "مَا مَنَعَكَ يَا فُلَانُ أَنْ تُصَلِّيَ مَعَ الْقَوْمِ؟" قَالَ: أَصَابَتْنِي جَنَابَةٌ وَلَا مَاءَ، قَالَ: "عَلَيْكَ بِالصَّعِيدِ فَإِنَّهُ يَكْفِيكَ". ثُمَّ سَارَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَاشْتَكَى إِلَيْهِ النَّاسُ مِنَ الْعَطَشِ، فَنَزَلَ فَدَعَا عَلِيًّا وَرَجُلًا آخَرَ فَقَالَ: اذْهَبَا فَابْتَغِيَا الْمَاءَ، فَانْطَلَقَا فَتَلَقَّيَا امْرَأَةً بَيْنَ مَزَادَتَيْنِ أَوْ سَطِيحَتَيْنِ مِنْ مَاءٍ عَلَى بَعِيرٍ لَهَا، فَقَالَا لَهَا: أَيْنَ الْمَاءُ؟ قَالَتْ: عَهْدِي بِالْمَاءِ أَمْسِ هَذِهِ السَّاعَةَ وَنَفَرُنَا خُلُوفٌ، فَقَالَا: انْطَلِقِي إِذًا، قَالَتْ: إِلَى أَيْنَ؟ قَالَا: إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَتْ: الَّذِي يُقَالُ لَهُ الصَّابِئُ؟ قَالَا: هُوَ الَّذِي تَعْنِينَ، فَانْطَلِقِي، فَجَاءَا بِهَا إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَحَدَّثَاهُ الْحَدِيثَ، قَالَ: "فَاسْتَنْزِلُوهَا عَنْ بَعِيرِهَا". وَدَعَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِإِنَاءٍ فَفَرَّغَ فِيهِ مِنْ أَفْوَاهِ الْمَزَادَتَيْنِ أَوْ سَطِيحَتَيْنِ، وَأَوْكَأَ أَفْوَاهَهُمَا، وَأَطْلَقَ الْعَزَالِيَ، وَنُودِيَ فِي النَّاسِ اسْقُوا وَاسْتَقُوا، فَسَقَى مَنْ سَقَى، وَاسْتَقَى مَنْ شَاءَ، وَكَانَ آخِرَ ذَالِكَ أَنْ أَعْطَى الَّذِي أَصَابَتْهُ الْجَنَابَةُ إِنَاءً مِنْ مَاءٍ، قَالَ: "اذْهَبْ فَأَفْرِغْهُ عَلَيْكَ". وَهِيَ قَائِمَةٌ تَنْظُرُ إِلَى مَا يُفْعَلُ بِمَائِهَا، وَايْمُ اللهِ لَقَدْ أُقْلِعَ عَنْهَا وَإِنَّهُ لَيُخَيَّلُ إِلَيْنَا أَنَّهَا أَشَدُّ مِلْأَةً مِنْهَا حِينَ ابْتَدَأَ فِيهَا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اجْمَعُوا لَهَا". فَجَمَعُوا لَهَا مِنْ بَيْنِ عَجْوَةٍ وَدَقِيقَةٍ وَسَوِيقَةٍ حَتَّى جَمَعُوا لَهَا طَعَامًا فَجَعَلُوهَا فِي ثَوْبٍ وَحَمَلُوهَا عَلَى بَعِيرِهَا، وَوَضَعُوا الثَّوْبَ بَيْنَ يَدَيْهَا، قَالَ لَهَا: "تَعْلَمِينَ مَا رَزِئْنَا مِنْ مَائِكِ شَيْئًا، وَلَكِنَّ اللهَ هُوَ الَّذِي أَسْقَانَا". فَأَتَتْ أَهْلَهَا وَقَدِ احْتَبَسَتْ عَنْهُمْ، فَقَالُوا: مَا حَبَسَكِ يَا فُلَانَةُ؟ قَالَتْ: الْعَجَبُ، لَقِيَنِي رَجُلَانِ فَذَهَبَا بِي إِلَى هَذَا الَّذِي يُقَالُ لَهُ الصَّابِئُ فَفَعَلَ كَذَا وَكَذَا، فَوَاللهِ إِنَّهُ لَأَسْحَرُ النَّاسِ مِنْ بَيْنِ هَذِهِ وَهَذِهِ، وَقَالَتْ بِإِصْبَعَيْهَا الْوُسْطَى وَالسَّبَّابَةِ فَرَفَعَتْهُمَا إِلَى السَّمَاءِ، تَعْنِي السَّمَاءَ وَالْأَرْضَ أَوْ إِنَّهُ لَرَسُولُ اللهِ حَقًّا، فَكَانَ الْمُسْلِمُونَ بَعْدَ ذَلِكَ يُغِيرُونَ عَلَى مَنْ حَوْلَهَا مِنَ الْمُشْرِكِينَ وَلَا يُصِيبُونَ الصِّرْمَ الَّذِي هِيَ مِنْهُ، فَقَالَتْ يَوْمًا لِقَوْمِهَا: مَا أُرَى أَنَّ هَؤُلَاءِ الْقَوْمَ يَدْعُونَكُمْ عَمْدًا فَهَلْ لَكُمْ فِي الْإِسْلَامِ؟ فَأَطَاعُوهَا فَدَخَلُوا فِي الْإِسْلَامِ. (ق)', 'ഇംറാനുബ്നു ഹുസൈയിൻ(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പം ഒരു യാത്രയിലായിരുന്നു. രാത്രി യാത്രചെയ്തു. അന്ത്യയാമത്തിലായപ്പോൾ യാത്രക്കാർ അഗാധ നിദ്രയിലായി. സൂര്യന്റെ ചൂട് തട്ടിയപ്പോൾ മാത്രമാണ് ഞങ്ങൾ ഉണർന്നത്. ആദ്യം ഇന്നയാളും പിന്നെ ഇന്നയാളും പിന്നെ ഇന്നയാളും നാലാമതായി ഉമറുബ്നുൽ ഖത്താബും(റ) ഉണർന്നു. നബി(സ) ഉറങ്ങിക്കഴിഞ്ഞാൽ സ്വയം ഉണരുകയല്ലാതെ ഞങ്ങൾ ഉണർത്താറുണ്ടായിരുന്നില്ല. കാരണം നബിക്ക് ഉറക്കത്തിൽ എന്തു സംഭവിക്കുന്നുവെന്ന് ഞങ്ങൾക്കറിയില്ലല്ലോ. ഉമർ(റ) ജനങ്ങളുടെ അവസ്ഥ കണ്ടപ്പോൾ ഉച്ചത്തിൽ തക്ബീർ ചൊല്ലി. നല്ല ശക്തിയുള്ള ആളായിരുന്നു അദ്ദേഹം. നബി(സ) ഉണരുന്നതുവരെ തക്ബീർ ചൊല്ലിക്കൊണ്ടേയിരുന്നു. നബി(സ) ഉണർന്നപ്പോൾ ജനങ്ങൾ കാര്യം ഉണർത്തി. നബി(സ) പറഞ്ഞു: "സാരമില്ല. ഉടനെ യാത്ര പുറപ്പെട്ടു കൊള്ളുക." അൽപം മുമ്പോട്ട് പോയശേഷം നബി(സ) യാത്ര നിർത്തി വാഹനത്തിൽ നിന്നിറങ്ങി. വെള്ളമാവശ്യപ്പെട്ടു, വുദു ചെയ്തു. നിസ്കാരത്തിനു ബാങ്ക് വിളിച്ചു. ജനങ്ങൾക്ക് ഇമാമായി നിസ്കരിച്ചു. നിസ്കാരത്തിൽ നിന്നു വിരമിച്ചപ്പോൾ ഒരാൾ സംഘത്തോടൊപ്പം നിസ്കരിക്കാതെ മാറിനിൽക്കുന്നു. നബി(സ) ചോദിച്ചു: "നിങ്ങൾ എന്തുകൊണ്ട് ജനങ്ങളോടൊപ്പം നിസ്കരിച്ചില്ല." അദ്ദേഹം പറഞ്ഞു: "എനിക്ക് വലിയ അശുദ്ധിയുണ്ടായിരുന്നു. വെള്ളമില്ല." നബി(സ) പറഞ്ഞു: "താങ്കൾ മണ്ണ് ഉപയോഗിക്കുക. താങ്കൾക്കത് മതി." നബി(സ) യാത്ര തുടർന്നു. ദാഹം മൂലം ജനങ്ങൾ ആവലാതിപ്പെടാൻ തുടങ്ങി. ഉടനെ വാഹനത്തിൽ നിന്നിറങ്ങി അലിയെയും മറ്റൊരാളെയും വിളിച്ചു നബി(സ) പറഞ്ഞു: "നിങ്ങൾ രണ്ടുപേരും പോയി കുറച്ച് വെള്ളം അന്വേഷിക്കുക." അവർ രണ്ടുപേരും പോയി കുറച്ച് ദൂരം ചെന്നപ്പോൾ ഒരൊട്ടകപ്പുറത്ത് രണ്ട് പാത്രം വെള്ളവും കയറ്റി അതിന്റെ നടുവിലിരുന്ന് ഒരു സ്ത്രീ യാത്ര ചെയ്യുന്നു. അവർ അവളോട് ചോദിച്ചു: എവിടെയാണ് വെള്ളമുള്ളത്?. അവൾ പറഞ്ഞു: ഞാൻ വെള്ളമുള്ള സ്ഥലത്തുനിന്നു ഇന്നലെ ഈ സമയത്ത് പുറപ്പെട്ടതാണ്. ഞങ്ങളുടെ സംഘത്തിലുള്ളവർ വെള്ളം കിട്ടാതെ അവിടെ തന്നെ കാത്ത് നിൽക്കുകയാണ്. അവർ അവളോട് പറഞ്ഞു: നീ ഞങ്ങളോടൊപ്പം വരൂ. അവൾ പറഞ്ഞു: എങ്ങോട്ട്? അവർ പറഞ്ഞു: "അല്ലാഹുവിന്റെ ദൂതന്റെ അടുക്കലേക്ക്." അവൾ പറഞ്ഞു: മതത്തിൽ നിന്നു വൃതിചലിച്ചുപോയി എന്ന് പറഞ്ഞുകേൾക്കുന്ന ആളുടെ അടുക്കലേക്കോ?" അവർ പറഞ്ഞു: "നീ ഉദ്ദേശിച്ച ആൾ തന്നെയാണത്. നീ നടക്കൂ." അവസാനം അവർ രണ്ടുപേരും അവളെയും കൂട്ടി നബി(സ)യുടെ മുമ്പിൽ ചെന്നു വിവരങ്ങൾ പറഞ്ഞു. അവളെ ഒട്ടകപ്പുറത്ത് നിന്നിറക്കാൻ നബി(സ) കൽപിച്ചു. നബി(സ) ഒരു പാത്രം ആവശ്യപ്പെട്ടു. ശേഷം ആ രണ്ടു തോൽപാത്രങ്ങളുടെയും വായ അഴിച്ച് തുറന്നുവെച്ചു. അതിന്റെ വലിയ വായ കെട്ടിയിട്ട് ചെറിയ വായ തുറന്നു വിട്ടു. "കുടിക്കാനോ മൃഗങ്ങൾക്ക് കുടിപ്പിക്കാനോ ആവശ്യമുള്ളവർ വെള്ളമെടുത്തു കൊള്ളുക" എന്നു ഉച്ചത്തിൽ വിളിച്ചു പറഞ്ഞു. അപ്പോൾ ആവശ്യമുള്ളവർ കുടിച്ചു. ആവശ്യമുള്ളവർ മൃഗങ്ങൾക്ക് കുടിപ്പിച്ചു. അവസാനം വലിയ അശുദ്ധിയുള്ളവനും ഒരു പാത്രം വെള്ളം കൊടുത്തിട്ട് നബി(സ) പറഞ്ഞു: "നീ പോയി ഇത് നിന്റെ ശരീരത്തിൽ ഒഴിക്കുക." ആ സ്ത്രീയാവട്ടെ അവളുടെ വെള്ളവും കൊണ്ട് ചെയ്യുന്നത് നോക്കിനിന്നു. അല്ലാഹുവാണെ! ആ തോൽപാത്രത്തിൽ നിന്ന് വെള്ളമെടുക്കുന്നത് നിർത്തിയപ്പോൾ അതിൽനിന്ന് വെള്ളമെടുക്കാൻ തുടങ്ങുമ്പോഴുണ്ടായിരുന്നതിനേക്കാൾ വെള്ളം അതിലുണ്ടെന്ന് ഞങ്ങൾക്ക് തോന്നി. അവസാനം നബി(സ) അരുളി: "അവൾക്ക് തിന്നാൻ വല്ലതും ശേഖരിച്ചു കൊടുക്കുക. ഈത്തപ്പഴം, മാവ്, ഗോതമ്പ് വറുത്തു പൊടിച്ചത് മുതലായ ആഹാര സാധനങ്ങൾ അവൾക്കുവേണ്ടി ശേഖരിച്ചു. അതൊരു തുണിയിൽ കെട്ടി അവളുടെ ഒട്ടകപ്പുറത്ത് വെച്ചുകൊടുത്തു. അവളെ ഒട്ടകപ്പുറത്ത് കയറ്റി നബി(സ) പറഞ്ഞു: "നിന്റെ വെള്ളത്തിൽ ഞങ്ങൾ ഒരു കുറവും വരുത്തിയിട്ടില്ല. അല്ലാഹുവാണ് ഞങ്ങൾക്ക് വെള്ളം തന്നത്." അങ്ങനെ അവൾ അവളുടെ കുടുംബത്തിൽ എത്തിച്ചേർന്നു. കുടുംബത്തിലെത്തിച്ചേരാൻ വൈകിയത് കണ്ടപ്പോൾ അവർ ചോദിച്ചു: എടീ, നീ വൈകിയെത്താൻ കാരണമെന്ത്?. അവൾ പറഞ്ഞു: അത്ഭുതം തന്നെ, എന്നെ രണ്ടു പുരുഷന്മാർ കണ്ടുമുട്ടി. മതത്തിൽ നിന്നു പുറത്ത് പോയവൻ എന്ന് നാം പറഞ്ഞു കേൾക്കാറുള്ള ആ മനുഷ്യന്റെ അടുക്കലേക്ക് എന്നെ അവർ കൊണ്ടുപോയി. അയാൾ ഇന്നയിന്ന പ്രകാരമെല്ലാം ചെയ്തു. ഏറ്റവും വലിയ മാന്ത്രികനാണദ്ദേഹം. ചൂണ്ടുവിരലും നടുവിരലും ആകാശത്തേക്ക് ചൂണ്ടിക്കൊണ്ടവൾ പറഞ്ഞു: തീർച്ചയായും അദ്ദേഹം അല്ലാഹുവിന്റെ ദൂതനാണ്. പിന്നീട് ആ സ്ത്രീയുടെ ഭാഗത്തുള്ള വരെ മുസ്ലിംകൾ അക്രമിച്ചില്ല. അവസാനം ഒരുദിവസം അവൾ തന്റെ ജനതയോട് പറഞ്ഞു: ഇക്കൂട്ടർ നിങ്ങളെ മനഃപൂർവ്വം ആക്രമിക്കാതെ വിട്ടിരിക്കയാണെന്നു തോന്നുന്നു. നിങ്ങൾക്ക് ഇസ്ലാമിൽ പ്രവേശിക്കാൻ ആഗ്രഹമുണ്ടോ?. അവളുടെ വാക്ക് അവർ സ്വീകരിച്ചു. അവർ ഇസ്ലാമിൽ പ്രവേശിച്ചു. (ബു,മു)', 'عِمْرَانَ بْنِ حُصَيْنٍ الْخُزَاعِيِّ', 'ഇംറാനുബ്നു ഹുസൈയിൻ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 194, 196, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ عَبْدِالرَّحْمَنِ بْنِ أَبْزَى رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ فَقَالَ: إِنِّي أَجْنَبْتُ فَلَمْ أُصِبِ الْمَاءَ، فَقَالَ عَمَّارُ بْنُ يَاسِرٍ لِعُمَرَ بْنِ الْخَطَّابِ: أَمَا تَذْكُرُ أَنَّا كُنَّا فِي سَفَرٍ أَنَا وَأَنْتَ، فَأَمَّا أَنْتَ فَلَمْ تُصَلِّ، وَأَمَّا أَنَا فَتَمَعَّكْتُ فَصَلَّيْتُ، فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا كَانَ يَكْفِيكَ هَكَذَا". فَضَرَبَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِكَفَّيْهِ الْأَرْضَ، وَنَفَخَ فِيهِمَا، ثُمَّ مَسَحَ بِهِمَا وَجْهَهُ وَكَفَّيْهِ. (خ,د,ن,جه)', 'അബ്ദുർറഹ്മാനുബ്നു അബ്സാ(റ): ഉമറുബ്നു ഖത്താബി(റ)ന്റെ അടുത്തുവന്ന് ഒരാൾ പറഞ്ഞു: എനിക്ക് വലിയ അശുദ്ധിയുണ്ടായി, വെള്ളം ലഭിച്ചതുമില്ല. അന്നേരം അമ്മാറുബ്നു യാസിർ ഉമറുബ്നുൽ ഖത്താബി(റ)നോട് പറഞ്ഞു: താങ്കൾ ഓർക്കുന്നില്ലേ?; നമ്മൾ ഒരു യാത്രയിൽ വലിയ അശുദ്ധിയുള്ളവരായി. അപ്പോൾ താങ്കൾ നിസ്കരിച്ചില്ല. ഞാൻ നിലത്തു കിടന്നുരുണ്ടശേഷം നിസ്കരിച്ചു. പിന്നെ ആ വിവരം നബി(സ)യോട് പറഞ്ഞപ്പോൾ "നിനക്കും അപ്രകാരം ചെയ്താൽ മതിയായിരുന്നു." എന്ന് പറഞ്ഞ്, നബി(സ) തന്റെ രണ്ട് കൈപ്പടങ്ങൾ നിലത്തടിച്ച് കൈകളിൽ ഊതുകയും മുഖവും കൈപടങ്ങളും തടവിക്കാണിക്കുകയും ചെയ്തു. (ബു,ദ,ന,ജ)', 'عَبْدِالرَّحْمَنِ بْنِ أَبْزَى', 'അബ്ദുർറഹ്മാനുബ്നു അബ്സാ(റ)', null, null, array['خ','د','ن','جه']::text[], array['ബു','ദ','ന','ജ']::text[], null, null, 196, 196, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: مَرَّ رَجُلٌ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي سِكَّةٍ مِنَ السِّكَكِ وَقَدْ خَرَجَ مِنْ غَائِطٍ أَوْ بَوْلٍ، فَسَلَّمَ عَلَيْهِ فَلَمْ يُرَدَّ عَلَيْهِ، حَتَّى إِذَا كَادَ الرَّجُلُ أَنْ يَتَوَارَى فِي السِّكَّةِ ضَرَبَ بِيَدَيْهِ عَلَى الْحَائِطِ وَمَسَحَ بِهِمَا وَجْهَهُ، ثُمَّ ضَرَبَ أُخْرَى فَمَسَحَ ذِرَاعَيْهِ، ثُمَّ رَدَّ عَلَى الرَّجُلِ السَّلَامَ، وَقَالَ: "إِنَّهُ لَمْ يَمْنَعْنِي أَنْ أَرُدَّ عَلَيْكَ السَّلَامَ إِلَّا أَنِّي لَمْ أَكُنْ عَلَى طُهْرٍ". (د)', 'ഇബ്നുഉമർ(റ): വിസർജ്ജനം കഴിഞ്ഞുവന്ന നബി(സ)യുടെ വഴിയിലൂടെ ഒരാൾ കടന്നുപോയി. അദ്ദേഹം നബി(സ)ക്ക് സലാം ചൊല്ലിയപ്പോൾ നബി(സ) സലാം മടക്കിയില്ല. വന്നയാൾ മറയാറാപ്പോൾ നബി(സ) ഒരു മതിലിൽ തന്റെ രണ്ടു കൈയും രണ്ട് പ്രാവശ്യം അടിച്ചു മുഖവും രണ്ട് കൈപടങ്ങളും തടവി. സലാം മടക്കിയശേഷം നബി(സ) പറഞ്ഞു: "സലാം മടക്കുന്നതിന് എനിക്കുണ്ടായിരുന്ന തടസ്സം ഞാൻ അശുദ്ധാവസ്ഥയിലായതായിരുന്നു എന്നതു മാത്രമാണ്." (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 196, 196, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ عَمَّارِ بْنِ يَاسِرٍ رَضِيَ اللهُ عَنْهُمَا: حِينَ تَيَمَّمُوا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَمَرَ الْمُسْلِمِينَ فَضَرَبُوا بِأَكُفِّهِمُ التُّرَابَ، وَلَمْ يَقْبِضُوا مِنَ التُّرَابِ شَيْئًا، فَمَسَحُوا بِوُجُوهِهِمْ مَسْحَةً وَاحِدَةً، ثُمَّ عَادُوا فَضَرَبُوا بِأَكُفِّهِمُ الصَّعِيدَ مَرَّةً أُخْرَى فَمَسَحُوا بِأَيْدِيهِمْ. (د,ت,ن,جه)', 'അമ്മാറുബ്നു യാസിർ(റ): നബി(സ)യോടൊപ്പം തയമ്മും ചെയ്തിരുന്ന മുസ്ലിംകൾ തങ്ങളോട് നബി(സ) കൽപിച്ചതുപ്രകാരം തങ്ങളുടെ കൈപ്പടങ്ങൾ മണ്ണിലടിച്ചു. പിന്നെ മുഖം ഒരു പ്രാവശ്യം തടവി. വീണ്ടും കൈപ്പടങ്ങൾ മണ്ണിലടിക്കുകയും ഇരു കൈകളും തടവുകയും ചെയ്തു. (ദ,തു,ന,ജ)', 'عَمَّارِ بْنِ يَاسِرٍ', 'അമ്മാറുബ്നു യാസിർ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 196, 197, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: إِجْتَمَعَتْ غُنَيْمَةٌ عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "يَا أَبَا ذَرٍّ، ابْدُ فِيهَا". فَبَدَوْتُ إِلَى الرَّبَذَةِ، فَكَانَتْ تُصِيبُنِي الْجَنَابَةُ فَأَمْكُثُ الْخَمْسَ وَالسِّتَّ، فَأَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَبُو ذَرٍّ". فَسَكَتُّ فَقَالَ: "ثَكِلَتْكَ أُمُّكَ أَبَا ذَرٍّ، لِأُمِّكَ الْوَيْلُ". فَدَعَا لِي بِجَارِيَةٍ سَوْدَاءَ، فَجَاءَتْ بِعُسٍّ فِيهِ مَاءٌ، فَسَتَرَتْنِي بِثَوْبٍ، وَاسْتَتَرْتُ بِالرَّاحِلَةِ، وَاغْتَسَلْتُ، فَكَأَنِّي أَلْقَيْتُ عَنِّي جَبَلًا، فَقَالَ: "الصَّعِيدُ الطَّيِّبُ وَضُوءُ الْمُسْلِمِ وَلَوْ إِلَى عَشْرِ سِنِينَ، فَإِذَا وَجَدْتَ الْمَاءَ فَأَمِسَّهُ جِلْدَكَ، فَإِنَّ ذَلِكَ خَيْرٌ". (د,ت,ن)', 'അബൂദർറ്(റ): അല്പം യുദ്ധാർജ്ജിതസ്വത്ത് നബി(സ)യുടെ അടുത്ത് ഒരുമിച്ചു കൂട്ടപ്പെട്ടു. നബി(സ) പറഞ്ഞു: "അബൂദർറേ, ഇവയുമായി നീ (ഏതെങ്കിലും) മലഞ്ചെരുവിലേക്ക് പുറപ്പെട്ടു കൊള്ളുക." അങ്ങനെ ഞാൻ റബദയിൽ പോയി. എനിക്ക് (അവിടെ നിന്ന്) ജനാബത്ത് ഉണ്ടാകും. അഞ്ചും ആറും (ദിവസമൊക്കെ ഞാനവിടെ) തങ്ങും. അങ്ങനെ ഞാൻ നബി(സ)യുടെ അടുക്കൽ ചെന്നു. നബി(സ) പറഞ്ഞു: "അബൂദർറേ" ഞാനൊന്നും മിണ്ടിയില്ല. അപ്പോൾ പറഞ്ഞു: "(ശ്ശോ! എന്തുപറ്റി നിനക്ക്?) നിന്റെ ഉമ്മക്ക് മകൻ ഇല്ലാതായോ?! അതോ, ഉമ്മാക്ക് വല്ല ദുരന്തവും പറ്റിയോ?" തുടർന്ന് നബി(സ) എനിക്കുവേണ്ടി കറുത്ത ഭൃത്യയെ വിളിച്ചു. അവൾ ഒരു വെള്ളപ്പാത്രവുമായി വന്നു. എന്നെ ഒരു വസ്ത്രം കൊണ്ട് മറച്ചു പിടിച്ചു. ഞാൻ വാഹനത്തിനപ്പുറം മറഞ്ഞു നിന്ന് കുളിച്ചു. ഒരു പർവ്വതം എന്നിൽ നിന്ന് വലിച്ചിട്ട പോലെയുണ്ട്! (ഭാരം ഒഴിവായതായി എനിക്ക് തോന്നി). നബി(സ) പറഞ്ഞു: "ശുദ്ധമായ മണ്ണ് മുസ്ലിമിന് ശുദ്ധീകരിക്കാനുള്ളതാണ്. പത്തുകൊല്ലം വരെയാണെങ്കിലും.! (എപ്പോഴെങ്കിലും) വെള്ളം കിട്ടിയാൽ തൊലിയിൽ സ്പർഷിക്കേണ്ടതാണ്. അത് ഗുണകരമായിരിക്കും." (ദ,തു,ന)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 197, 197, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللهُ عَنْهُ قَالَ: احْتَلَمْتُ فِي لَيْلَةٍ بَارِدَةٍ فِي غَزْوَةِ ذَاتِ السُّلَاسِلِ فَأَشْفَقْتُ إِنِ اغْتَسَلْتُ أَنْ أَهْلِكَ، فَتَيَمَّمْتُ ثُمَّ صَلَّيْتُ بِأَصْحَابِي الصُّبْحَ، فَذَكَرُوا ذَلِكَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "يَا عَمْرُو، صَلَّيْتَ بِأَصْحَابِكَ وَأَنْتَ جُنُبٌ" فَأَخْبَرْتُهُ بِالَّذِي مَنَعَنِي مِنَ الْاغْتِسَالِ، وَقُلْتُ: إِنِّي سَمِعْتُ اللهَ يَقُولُ: {وَلَا تَقْتُلُوا أَنْفُسَكُمْ إِنَّ اللهَ كَانَ بِكُمْ رَحِيمًا} [النساء:٢٩] فَضَحِكَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَلَمْ يَقُلْ شَيْئًا.وفي رواية: قال: فغسل مغابنه، وتوضأ وضوءه للصلاة، ثم صلى بهم، فذكر نحوه، ولم يذكر التيمم. (د)', 'അംറുബ്നുൽആസ്(റ): സുലാസിൽ യുദ്ധകാലത്ത് എനിക്ക് സ്വപ്നസ്ഖലനമുണ്ടായി. അന്ന് കുളിച്ചാൽ മരിച്ചു പോകുമോ എന്ന് ഞാൻ ഭയന്നു. അത്രയും കടുത്ത തണുപ്പായിരുന്നു. അങ്ങനെ ഞാൻ തയമ്മും ചെയ്തു. എന്റെ കൂട്ടുകാരെയും കൂട്ടി ഞാൻ നിസ്കരിച്ചു. അവരത് നബി(സ)യോട് പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "അംറേ, നീ ജനാബത്തുകാരനായിരിക്കെ നിന്റെ സഹപ്രവർത്തകർക്ക് ഇമാമായി നിസ്കരിച്ചോ?." അപ്പോൾ ഞാൻ കുളിക്കാതിരിക്കാനുള്ള കാരണം വിശദീകരിച്ചു കൊടുത്തു. ശേഷം പറഞ്ഞു: അല്ലാഹു പറഞ്ഞത് ഞാൻ കേട്ടിട്ടുണ്ട്. "നിങ്ങൾ നിങ്ങളുടെ ശരീരങ്ങളെ കൊന്നു കളയരുത്, അല്ലാഹു നിങ്ങളോട് കരുണയുള്ളവനാണ്."(നിസാഅ് 29). ഇത് കേട്ട് നബി(സ) ചിരിച്ചു. ഒന്നും മിണ്ടിയില്ല. മറ്റൊരു റിപ്പോർട്ടിൽ: ദേഹത്ത് അഴുക്ക് തങ്ങിനിൽക്കുന്ന ഭാഗങ്ങൾ മാത്രം കഴുകി നിസ്കാരത്തിന് വുദു ചെയ്തു നിസ്കരിച്ചു. തുടർന്ന് മേൽപ്രകാരം പറഞ്ഞു. അതിൽ തയമ്മുമിനെ കുറിച്ച് പരാമർശമില്ല. (ദ)', 'عَمْرِو بْنِ الْعَاصِ', 'അംറുബ്നുൽആസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], 'النساء:٢٩', null, 197, 197, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=12 and h.hadith_no=8), 1, 'وَفِي رِوَايَةٍ: قال: فغسل مغابنه، وتوضأ وضوءه للصلاة، ثم صلى بهم، فذكر نحوه، ولم يذكر التيمم. (د)', 'മറ്റൊരു നിവേദനിൽ: ദേഹത്ത് അഴുക്ക് തങ്ങിനിൽക്കുന്ന ഭാഗങ്ങൾ മാത്രം കഴുകി നിസ്കാരത്തിന് വുദു ചെയ്തു നിസ്കരിച്ചു. തുടർന്ന് മേൽപ്രകാരം പറഞ്ഞു. അതിൽ തയമ്മുമിനെ കുറിച്ച് പരാമർശമില്ല. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجَ رَجُلَانِ فِي سَفَرٍ، فَحَضَرَتِ الصَّلَاةُ وَلَيْسَ مَعَهُمَا مَاءٌ، فَتَيَمَّمَا صَعِيدًا طَيِّبًا، فَصَلَّيَا، ثُمَّ وَجَدَا الْمَاءَ فِي الْوَقْتِ، فَأَعَادَ أَحَدُهُمَا الصَّلَاةَ وَالْوُضُوءَ وَلَمْ يُعِدِ الْآخَرُ، ثُمَّ أَتَيَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَا ذَلِكَ لَهُ، فَقَالَ لِلَّذِي لَمْ يُعِدْ: "أَصَبْتَ السُّنَّةَ وَأَجْزَأَتْكَ صَلَاتُكَ" وَقَالَ لِلَّذِي تَوَضَّأَ وَأَعَادَ: "لَكَ الْأَجْرُ مَرَّتَيْنِ" (خ,د,ن)', 'അബൂസഈദുൽ ഖുദ്രി(റ): രണ്ടാളുകൾ യാത്ര ചെയ്യുകയായിരുന്നു. നിസ്കാര സമയമായപ്പോൾ അവരുടെ അടുക്കൽ വെള്ളമില്ലായിരുന്നു. അവർ നല്ല മണ്ണെടുത്തു തയമ്മും ചെന്തു നിസ്കരിച്ചു. അനന്തരം ആ നിസ്കാര സമയത്ത് തന്നെ വെള്ളം കിട്ടിയപ്പോൾ ഒരാൾ വുദു ചെയ്തു വീണ്ടും നിസ്കരിച്ചു. രണ്ടാമൻ അത് ചെയ്തില്ല. പിന്നീട് രണ്ടുപേരും നബി(സ)യുടെ അടുക്കൽ വന്ന് വിവരം പറഞ്ഞു. അപ്പോൾ നിസ്കാരം ആവർത്തിക്കാത്തവനോട് നബി(സ) പറഞ്ഞു: "നീ സുന്നത്ത് അനുഷ്ടിച്ചു. നിനക്ക് ആ നിസ്കാരം മതി." വുദുചെയ്ത് നിസ്കാരം ആവർത്തിച്ചവനോട് നബി(സ)പറഞ്ഞു: "നിനക്ക് ഇരട്ടി പ്രതിഫലമുണ്ട്." (ബു,ദ,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['خ','د','ن']::text[], array['ബു','ദ','ന']::text[], null, null, 198, 198, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْنَا فِي سَفَرٍ، فَأَصَابَ رَجُلًا مِنَّا حَجَرٌ فَشَجَّهُ فِي رَأْسِهِ، ثُمَّ احْتَلَمَ، فَسَأَلَ أَصْحَابَهُ فَقَالَ: هَلْ تَجِدُونَ لِي رُخْصَةً فِي التَّيَمُّمِ؟ فَقَالُوا: مَا نَجِدُ لَكَ رُخْصَةً وَأَنْتَ تَقْدِرُ عَلَى الْمَاءِ، فَاغْتَسَلَ، فَمَاتَ، فَلَمَّا قَدِمْنَا عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أُخْبِرَ بِذَلِكَ، فَقَالَ: "قَتَلُوهُ قَتَلَهُمُ اللهُ، أَلَا سَأَلُوا إِذْ لَمْ يَعْلَمُوا، فَإِنَّمَا شِفَاءُ الْعِيِّ السُّؤَالُ، إِنَّمَا كَانَ يَكْفِيهِ أَنْ يَتَيَمَّمَ وَيَعْصِرَ - أَوْ يَعْصِبَ - عَلَى جُرْحِهِ خِرْقَةً ثُمَّ يَمْسَحَ عَلَيْهَا وَيَغْسِلَ سَائِرَ جَسَدِهِ". (د)', 'ജാബിർ(റ): ഞങ്ങൾ ഒരു യാത്ര ചെയ്തു. ഒരാൾക്ക് കല്ലുകൊണ്ട് തലക്ക് മുറിവേറ്റു. പിന്നെ അയാൾക്ക് സ്വപ്നസ്ഖലനമുണ്ടാകുകയും ചെയ്തു. എനിക്ക് തയമ്മും ചെയ്യാൻ വല്ല ഇളവും ഉണ്ടോ? എന്ന് അയാൾ തന്റെ സ്നേഹിതന്മാരോട് ചോദിച്ചപ്പോൾ വെള്ളമുണ്ടായിരിക്കെ നിനക്ക് യാതൊരു ഇളവും കാണുന്നില്ലെന്ന് അവർ പറഞ്ഞു. അങ്ങനെ അയാൾ കുളിച്ചതുമൂലം മരണമടയുകയും ചെയ്തു. ഞങ്ങൾ നബി(സ)യുടെ അടുത്തുചെന്ന് വിവരം പറഞ്ഞപ്പോൾ നബി(സ) പറഞ്ഞു: "അയാളെ അവർ കൊന്നു. അല്ലാഹു അവരെയും കൊല്ലട്ടെ. അവർക്കറിയില്ലെങ്കിൽ ചോദിക്കാമായിരുന്നില്ലേ?. ചോദിച്ചറിയൽ മാത്രമാണ് അജ്ഞതക്കുള്ള ചികിത്സ. അയാൾക്ക് തയമ്മും ചെയ്യാമായിരുന്നു. അല്ലെങ്കിൽ മുറിവിന്മേൽ ബാന്റേജ് കെട്ടി അതിന്മേൽ തടവുകയും ശരീരത്തിന്റെ മറ്റുഭാഗങ്ങൾ കഴുകുകയും ചെയ്താൽ മതിയായിരുന്നു." (ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 198, 198, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
